package dev.pocketengine.features.teams;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
public final class TeamRemoteModelViewTest {
    @Test public void fullPackageNativeAuditIsNotRepeatedIntoModelHistory()throws Exception{JSONArray manifest=new JSONArray();for(int i=0;i<2000;i++)manifest.put(new JSONObject().put("path","source-"+i).put("sha256","a".repeat(64)));JSONObject actual=new JSONObject().put("status","ready").put("ok",true).put("packageManifest",new JSONObject().put("files",manifest)).put("context",new JSONObject().put("secretFixtureOnly","not-a-real-secret"));String before=actual.toString();JSONObject ref=new JSONObject().put("kind","original_team_remote_operation_receipt").put("operationId","original-op");JSONObject visible=TeamRemoteModelView.project(actual,ref);assertTrue(visible.toString().length()<1000);assertFalse(visible.has("packageManifest"));assertFalse(visible.has("context"));assertFalse(visible.getBoolean("completeOriginalResultReturned"));assertTrue(visible.getBoolean("nativeReceiptRetained"));assertEquals(before,actual.toString());}
    @Test public void unknownAndOriginalArtifactReferencesRemainExactRatherThanFakeCompleted()throws Exception{JSONArray refs=new JSONArray().put(new JSONObject().put("artifactId","native-original").put("sha256","absent").put("artifactKind","file_tombstone"));JSONObject actual=new JSONObject().put("status","unknown").put("accepted",JSONObject.NULL).put("ok",false).put("teamArtifacts",refs);JSONObject visible=TeamRemoteModelView.project(actual,null);assertTrue(visible.isNull("accepted"));assertEquals("unknown",visible.getString("status"));assertFalse(visible.getBoolean("ok"));assertFalse(visible.getBoolean("nativeReceiptRetained"));assertEquals(refs.toString(),visible.getJSONArray("teamArtifacts").toString());assertFalse(visible.has("nativeReceiptRef"));}
}
